import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  RepeatWrapping
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load background texture from atlas region
  const texUrl =
    config.assets?.find(a => a.type === 'imageUrl')?.url ||
    '/prism-mock/home/nodes/floating-accent.png';
  const texture = ctx.textureLoader.load(texUrl);

  // Atlas source rect: (0,0,512,320)
  // Assume texture may be larger than region -> compute UV repeat
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;
  // If texture image dimensions known (synchronous), use them; otherwise assume 1x1
  const img = texture.image;
  const texW = img?.width || 512;
  const texH = img?.height || 320;
  const srcW = 512;
  const srcH = 320;
  texture.offset.set(0, 0);
  texture.repeat.set(srcW / texW, srcH / texH);

  // Plane dimensions based on atlas aspect ratio
  const aspect = srcW / srcH;
  const height = 1.0; // base unit – adjust as needed
  const width = height * aspect;

  const bgGeo = new PlaneGeometry(width, height);
  const bgMat = new MeshBasicNodeMaterial({ map: texture, transparent: true });
  const bgMesh = new Mesh(bgGeo, bgMat);
  group.add(bgMesh);

  // Text content – "Journal" headline
  const textEntry = config.textContent?.find(t => t.role === 'headline');
  if (textEntry) {
    const textMesh = ctx.fontAtlas.createText({
      text: textEntry.text,
      fontFamily: 'Lora',
      fontWeight: 400,
      fontSize: 0.62, // hero depth (scene units)
      color: '#e8ecf2', // paper against dark background
      align: 'center'
    });
    // Slight z offset to avoid z-fighting with background plane
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  }

  // Scene placement from config
  const sp = config.scenePlacement || {};
  group.position.set(
    sp.position?.[0] ?? 0,
    sp.position?.[1] ?? 3,
    sp.position?.[2] ?? 0
  );
  group.rotation.set(
    sp.rotation?.[0] ?? 0,
    sp.rotation?.[1] ?? 0,
    sp.rotation?.[2] ?? 0
  );
  group.scale.set(
    sp.scale?.[0] ?? 1,
    sp.scale?.[1] ?? 1,
    sp.scale?.[2] ?? 1
  );

  // Billboard behaviour – update handler keeps the group facing the camera
  const textMeshRef = textEntry ? group.children[1] : null; // safe reference
  group.userData.handlers = {
    update: (camera) => {
      group.lookAt(camera.position);
    }
  };

  // Cleanup – dispose geometry, material, texture, and any text resources
  group.userData.cleanup = () => {
    bgGeo.dispose();
    bgMat.dispose();
    texture.dispose();
    if (textMeshRef) {
      textMeshRef.geometry.dispose();
      textMeshRef.material.dispose();
    }
    // No GSAP timelines to kill
  };

  // No cinematic primitives to apply
  // (config.cinematicPrimitives is empty)

  return group;
}
